// <auto-generated/>
namespace Sunplus.Accounting.Business.Customer
{
    using System;
    using System.Collections.Generic;
    using System.Text;
    using System.Web;
    using System.Xml;
    using DNAide.Web;
    using Sunplus.Accounting.Core.Web;
    using System.Linq;
    using Sunplus.Accounting.DataAccess.IBCDLL.Accounting;
    using GlobalResources;

    public class DangerousSetting
    {  
        private IList<DangerousDetail> settings;

        private IDictionary<string, string> dangerTypeDictionary = new Dictionary<string, string>
        {
            { CustomerInfoResources.Danger1, "1"},
            { CustomerInfoResources.Danger2, "2" },
            { CustomerInfoResources.Danger3, "3"}
        };

        private DangerousDetail BASetting = new DangerousDetail(-1, "BA", "#000000");

        public DangerousSetting()
        {
            GetDangerSettingOriginal();          
        }

        private void GetDangerSettingOriginal()
        {
            string configFileName = HttpContext.Current.Server.MapPath("~/App_Data/DangerousSetting.xml");
            XmlDocument xmlDoc = new XmlDocument();
            xmlDoc.Load(configFileName);
            XmlNodeList levels = xmlDoc.GetElementsByTagName("level");

            settings = new List<DangerousDetail>();
            foreach (XmlNode level in levels)
            {
                settings.Add(
                    new DangerousDetail(
                        Convert.ToInt32(level.Attributes["id"].Value), 
                        level.Attributes["name"].Value, 
                        level.Attributes["color"].Value,
                        level.Attributes["background"].Value));
            }
        }

        private DangerousDetail GetDangerousLevelSetting(int level, string dangeruostype, bool isBA)
        {
            var isMarkedBA = (level == 0 && isBA) || level == 100;
            var isDanger1 = dangeruostype == CustomerInfoResources.Danger1 || 
                dangeruostype == dangerTypeDictionary[CustomerInfoResources.Danger1];

            if (isDanger1 && isMarkedBA)
            {
                return BASetting;
            }

            return settings.Where(item => item.Id == level).FirstOrDefault();
        }

        public string GenDangerous(
            int roleId, 
            bool isManageCustomerAccess, 
            IList<DangerousType> dangerousTypes, 
            bool isBA,
            string searchAccountRoleName)
        {
            string dangerous = string.Empty, 
                s_ = string.Empty, 
                s = WebUtils.LoadTemplate("DangerousCust.htm");

            foreach(var dangerousType in dangerousTypes)
            {
                var dangerLevelSetting = GetDangerousLevelSetting(dangerousType.Id, dangerousType.Name, isBA);

                s_ = (string)s.Clone();
                TemplateHandler.Assign(ref s_, "{downline_level_name}", searchAccountRoleName);

                TemplateHandler.Assign(ref s_, "{name}", dangerousType.Name.Replace(" ", ""));
                TemplateHandler.Assign(ref s_, "{dangername}", dangerousType.Name);
                TemplateHandler.Assign(ref s_, "{value}", dangerLevelSetting.Name);

                TemplateHandler.Assign(ref s_, "{danger_level_style}", 
                    $"style='color:{dangerLevelSetting.Color}; background-color:{dangerLevelSetting.BackgroundColor}'");

                TemplateHandler.Assign(ref s_, "{currentLevel}", dangerousType.Id.ToString());

                if (isManageCustomerAccess)
                {
                    TemplateHandler.Assign(ref s_, "{onclick}", "OpenCloseMenuDangerous(this,'divLevel" + dangerousType.Name.Replace(" ", "") + "'," + dangerousType.Id.ToString() + ");");
                    string levelItem = TemplateHandler.CopyBlock(s_, "LevelItem");
                    TemplateHandler.RemoveBlock(ref s_, "LevelItem");
                    StringBuilder content = new StringBuilder();

                    foreach (DangerousDetail setting in settings)
                    {
                        string row = Convert.ToString(levelItem.Clone());
                        TemplateHandler.Assign(ref row, "{level_style}",
                            $"style='color:{setting.Color}; background-color:{setting.BackgroundColor}'");
                        TemplateHandler.Assign(ref row, "{LevelName}", setting.Name);
                        TemplateHandler.Assign(ref row, "{LevelID}", setting.Id);

                        TemplateHandler.Assign(ref row, "{type}", dangerousType.Name);
                        var dangerousTpe = dangerTypeDictionary[dangerousType.Name];
                        TemplateHandler.Assign(ref row, "{dangerousType}", dangerousTpe);

                        var levelOnClick = roleId == 1 ?
                            $"return ChangeDangerousLevel('{dangerousType.Name}',{setting.Id},'{setting.Name}','{setting.Color}');" :
                            $"return ChangeDangerousLevelAgent('{dangerousType.Name}',{dangerousTpe},'{setting.Id}');";

                        TemplateHandler.Assign(ref row, "{level_onclick}", levelOnClick);
                        content.Append(row);
                    }

                    TemplateHandler.Assign(ref s_, "{content}", content.ToString());
                }
                else
                {
                    TemplateHandler.Assign(ref s_, "{onclick}", string.Empty);
                    TemplateHandler.RemoveBlock(ref s_, "ImgDropdownLevel");
                    TemplateHandler.RemoveBlock(ref s_, "DropdownLevel");
                }

                dangerous += s_;
            }

            return dangerous;
        }

        public DangerousDetail CustomerUpdateDangerous(int accid, int custid, int dangerLevel, int dangertype)
        {
            var isBA = CustomerUpdateStatus.CustomerUpdateDangerous(accid, custid, dangerLevel, dangertype);
            return GetDangerousLevelSetting(dangerLevel, dangertype.ToString(), isBA);
        }
    }
}